import React from 'react';
import { Outlet, Link, useNavigate } from 'react-router-dom';

function Layout() {
    const navigate = useNavigate();

    return (
        <div style={{ display: 'flex', minHeight: '100vh' }}>
            {/* Sidebar */}
            <div style={{
                width: '250px',
                backgroundColor: '#1976d2',
                color: 'white',
                padding: '20px'
            }}>
                <h2 style={{ marginBottom: '30px' }}>🛡️ ISO</h2>
                <nav>
                    <div style={{ marginBottom: '15px' }}>
                        <Link to="/dashboard" style={{ color: 'white', textDecoration: 'none' }}>
                            📊 داشبورد
                        </Link>
                    </div>
                    <div style={{ marginBottom: '15px' }}>
                        <Link to="/anomalies" style={{ color: 'white', textDecoration: 'none' }}>
                            ⚠️ آنومالی‌ها
                        </Link>
                    </div>
                    <div style={{ marginBottom: '15px' }}>
                        <button
                            onClick={() => {
                                localStorage.removeItem('user');
                                navigate('/login');
                            }}
                            style={{
                                background: 'none',
                                border: 'none',
                                color: 'white',
                                cursor: 'pointer',
                                fontSize: '16px'
                            }}
                        >
                            🚪 خروج
                        </button>
                    </div>
                </nav>
            </div>

            {/* Main Content */}
            <div style={{
                flex: 1,
                padding: '30px',
                backgroundColor: '#f5f7fa'
            }}>
                <Outlet />
            </div>
        </div>
    );
}

export default Layout;
